package com.andye.warmod.radar.station;import java.util.UUID;public final class RadarSweepMath {private RadarSweepMath(){}public static long phaseOffset(UUID id){return Math.floorMod(id.getMostSignificantBits()^id.getLeastSignificantBits(),RadarStationConstants.SWEEP_PERIOD_TICKS);}public static double angleDegrees(double gameTime,long phase){double cycle=Math.floorMod((long)Math.floor(gameTime)+phase,RadarStationConstants.SWEEP_PERIOD_TICKS)+(gameTime-Math.floor(gameTime));return cycle/RadarStationConstants.SWEEP_PERIOD_TICKS*360.0;}public static double bearing(double dx,double dz){double a=Math.toDegrees(Math.atan2(-dx,dz));return a<0?a+360:a;}public static boolean crossed(double previous,double current,double bearing,double width){double travel=positive(current-previous),to=positive(bearing-previous);return to<=travel+width*.5||positive(previous-bearing)<=width*.5;}private static double positive(double a){a%=360;if(a<0)a+=360;return a;}}